export function motionRetainedVideoFixture(name: MotionRetainedVideoFixture): Buffer {
	const metadata = MOTION_RETAINED_VIDEO_FIXTURES[name];
	const bytes = gunzipSync(Buffer.from(ENCODED[name], 'base64'), { maxOutputLength: 128 * 1024 });
	if (bytes.byteLength !== metadata.byteLength || createHash('sha256').update(bytes).digest('hex') !== metadata.sha256) throw new Error('The retained motion video fixture failed its byte identity check.');
	return bytes;
}

/** The UI tracking fixture always uses original retained media, including on WebKit. */
export function motionTrackingVideo(_page: Page, { frameCount = 120, greenScreen = false }: { frameCount?: number; greenScreen?: boolean } = {}): Promise<Buffer> {
	if (frameCount === 120 && !greenScreen) return Promise.resolve(motionRetainedVideoFixture('checker120'));
	if (frameCount === 6 && greenScreen) return Promise.resolve(motionRetainedVideoFixture('green6'));
	throw new RangeError('Only the recorded 120-frame checker and six-frame green-screen fixture are retained.');
}
